const WHATSAPP_NUMBER = '5513978124333';
const assetPathPattern = /^assets\/[A-Za-z0-9_./-]+\.(?:webp|jpe?g)$/i;
const vehicleGrid=document.getElementById("vehicleGrid");
const brandFilters=document.getElementById("brandFilters");
const vehicleSearch=document.getElementById("vehicleSearch");
const catalogCount=document.getElementById("catalogCount");
const vehicleModal=document.getElementById("vehicleModal");
const vehicleModalHost=document.getElementById("vehicleModalHost");
let activeFilter="todos";
let activeVehicle=null;
let activeGalleryIndex=0;
let returnFocus=null;

function make(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function makeImage(info,{eager=false}={}){const image=make("img");if(!info||!assetPathPattern.test(info.src)||info.src.split("/").includes(".."))return image;image.src=info.src;image.alt=info.alt||"";image.width=info.width;image.height=info.height;image.loading=eager?"eager":"lazy";image.decoding="async";if(eager)image.fetchPriority="high";return image;}
function observeReveal(scope=document){const nodes=scope.querySelectorAll(".reveal:not(.is-visible)");if(!("IntersectionObserver" in window)){nodes.forEach(node=>node.classList.add("is-visible"));return;}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("is-visible");observer.unobserve(entry.target);}}),{threshold:.12});nodes.forEach(node=>observer.observe(node));}
function categoryLabel(category){if(category==="outras")return "Outras";const record=vehicles.find(vehicle=>vehicle.category===category);return record?.brandYear.split("•")[0].trim()||category;}

function renderFilters(){const categories=[...new Set(vehicles.map(vehicle=>vehicle.category))].sort((a,b)=>a==="outras"?1:b==="outras"?-1:categoryLabel(a).localeCompare(categoryLabel(b),"pt-BR"));const buttons=[{id:"todos",label:"Todos"},...categories.map(id=>({id,label:categoryLabel(id)}))].map((item,index)=>{const button=make("button",`filter${index===0?" active":""}`,item.label);button.type="button";button.dataset.filter=item.id;button.setAttribute("aria-pressed",String(index===0));return button;});brandFilters.replaceChildren(...buttons);brandFilters.addEventListener("click",event=>{const button=event.target.closest("button[data-filter]");if(!button)return;activeFilter=button.dataset.filter;brandFilters.querySelectorAll(".filter").forEach(filter=>{const selected=filter===button;filter.classList.toggle("active",selected);filter.setAttribute("aria-pressed",String(selected));});updateCatalog();});}

function renderCard(vehicle){const card=make("article","vehicle-card vehicle-card-featured reveal");card.dataset.category=vehicle.category;card.dataset.search=vehicle.search;card.dataset.openVehicle=vehicle.id;card.tabIndex=0;card.setAttribute("role","button");card.setAttribute("aria-label",vehicle.ariaLabel||`Ver detalhes de ${vehicle.title}`);const photo=make("div","vehicle-image vehicle-image-photo");photo.append(makeImage(vehicle.cardImage));if(vehicle.badge)photo.append(make("span","",vehicle.badge));photo.append(make("div","vehicle-image-gradient"));photo.append(make("div","vehicle-photo-action","Ver detalhes ↗"));const info=make("div","vehicle-info"),details=make("div");details.append(make("small","",vehicle.brandYear),make("h3","",vehicle.name),make("p","",vehicle.summary));info.append(details,make("strong","",vehicle.price));const cta=make("div","vehicle-cta vehicle-cta-static");cta.append(make("span","","Ver fotos e informações"),make("span","","→"));card.append(photo,info,cta);card.addEventListener("click",()=>openVehicle(vehicle,card));card.addEventListener("keydown",event=>{if(event.target===card&&(event.key==="Enter"||event.key===" ")){event.preventDefault();openVehicle(vehicle,card);}});return card;}
function renderInventory(){vehicleGrid.replaceChildren(...vehicles.map(renderCard));renderFilters();observeReveal(vehicleGrid);updateCatalog();}
function updateCatalog(){const query=(vehicleSearch?.value||"").trim().toLocaleLowerCase("pt-BR");let visible=0;vehicleGrid.querySelectorAll(".vehicle-card").forEach(card=>{const matchesCategory=activeFilter==="todos"||card.dataset.category===activeFilter;const matchesText=!query||(card.dataset.search||"").toLocaleLowerCase("pt-BR").includes(query);const show=matchesCategory&&matchesText;card.classList.toggle("hide",!show);if(show)visible++;});if(catalogCount)catalogCount.textContent=visible===1?"1 veículo disponível":`${visible} veículos disponíveis`;}
vehicleSearch?.addEventListener("input",updateCatalog);

function safeWhatsApp(message){const url=new URL(`https://wa.me/${WHATSAPP_NUMBER}`);url.searchParams.set("text",message);return url.href;}
function vehicleMessage(vehicle,kind){const price=vehicle.price&&vehicle.price!=="Consultar"?` por ${vehicle.price}`:"";if(kind==="simulation")return `Olá Braga Veículos! Tenho interesse no ${vehicle.title}${price} e quero fazer uma simulação.`;return `Olá Braga Veículos! Quero mais informações sobre o ${vehicle.title}.`;}
function actionLink(label,href,primary=false){const link=make("a",`btn ${primary?"btn-primary":"btn-ghost"} btn-full`,label);link.href=href;link.target="_blank";link.rel="noopener noreferrer";return link;}
function renderGallery(vehicle){const gallery=make("div","vehicle-gallery");const mainWrap=make("div","vehicle-gallery-main");const main=makeImage(vehicle.gallery[0],{eager:true});main.id="vehicleGalleryMain";mainWrap.append(main);if(vehicle.gallery.length>1){const previous=make("button","gallery-arrow prev","‹");previous.type="button";previous.setAttribute("aria-label","Foto anterior");previous.addEventListener("click",()=>setGallery(activeGalleryIndex-1));const next=make("button","gallery-arrow next","›");next.type="button";next.setAttribute("aria-label","Próxima foto");next.addEventListener("click",()=>setGallery(activeGalleryIndex+1));mainWrap.append(previous,next);}gallery.append(mainWrap);if(vehicle.gallery.length>1){const thumbs=make("div","vehicle-thumbs");vehicle.gallery.forEach((image,index)=>{const button=make("button",`vehicle-thumb${index===0?" active":""}`);button.type="button";button.setAttribute("aria-label",`Mostrar foto ${index+1} de ${vehicle.gallery.length}`);button.setAttribute("aria-pressed",String(index===0));button.append(makeImage(image));button.addEventListener("click",()=>setGallery(index));thumbs.append(button);});gallery.append(thumbs);}return gallery;}
function setGallery(index){if(!activeVehicle)return;const length=activeVehicle.gallery.length;activeGalleryIndex=(index+length)%length;const image=activeVehicle.gallery[activeGalleryIndex];const main=document.getElementById("vehicleGalleryMain");if(main){main.src=image.src;main.alt=image.alt;main.width=image.width;main.height=image.height;}vehicleModalHost.querySelectorAll(".vehicle-thumb").forEach((button,i)=>{const selected=i===activeGalleryIndex;button.classList.toggle("active",selected);button.setAttribute("aria-pressed",String(selected));});}
function renderModal(vehicle){const grid=make("div","vehicle-modal-grid");grid.append(renderGallery(vehicle));const content=make("div","vehicle-modal-content");content.append(make("span","kicker",vehicle.kicker),make("h2","",vehicle.title));const title=content.querySelector("h2");title.id="vehicleModalTitle";content.append(make("p","vehicle-modal-price",vehicle.price));const specs=make("div","vehicle-specs");vehicle.specs.forEach(item=>{const box=make("div");box.append(make("small","",item.label),make("strong","",item.value));specs.append(box);});content.append(specs,make("div","vehicle-modal-divider"),make("h3","","Sobre este veículo"),make("p","vehicle-modal-text",vehicle.description));if(vehicle.highlights.length){const list=make("ul","vehicle-modal-highlights");vehicle.highlights.forEach(text=>list.append(make("li","",text)));content.append(list);}const actions=make("div","vehicle-modal-actions");actions.append(actionLink("Fazer simulação",safeWhatsApp(vehicleMessage(vehicle,"simulation")),true),actionLink("Falar sobre este veículo",safeWhatsApp(vehicleMessage(vehicle,"details"))));content.append(actions,make("small","vehicle-disclaimer","Preço e disponibilidade sujeitos à confirmação da loja."));grid.append(content);vehicleModalHost.replaceChildren(grid);}
function openVehicle(vehicle,opener){activeVehicle=vehicle;activeGalleryIndex=0;returnFocus=opener;renderModal(vehicle);vehicleModal.classList.add("open");vehicleModal.setAttribute("aria-hidden","false");document.body.classList.add("modal-open");vehicleModal.querySelector(".vehicle-modal-close")?.focus();}
function closeVehicle(){if(!vehicleModal?.classList.contains("open"))return;vehicleModal.classList.remove("open");vehicleModal.setAttribute("aria-hidden","true");document.body.classList.remove("modal-open");vehicleModalHost.replaceChildren();activeVehicle=null;returnFocus?.focus?.();}
vehicleModal?.querySelectorAll("[data-close-modal]").forEach(button=>button.addEventListener("click",closeVehicle));
document.addEventListener("keydown",event=>{if(!vehicleModal?.classList.contains("open"))return;if(event.key==="Escape"){closeVehicle();return;}if(event.key==="ArrowLeft"){setGallery(activeGalleryIndex-1);return;}if(event.key==="ArrowRight"){setGallery(activeGalleryIndex+1);return;}if(event.key==="Tab"){const focusable=[...vehicleModal.querySelectorAll("button,a[href]")].filter(node=>!node.disabled);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

const menuToggle=document.querySelector(".menu-toggle"),nav=document.querySelector(".nav");if(menuToggle&&nav){menuToggle.addEventListener("click",()=>{const open=nav.classList.toggle("open");menuToggle.setAttribute("aria-expanded",String(open));menuToggle.setAttribute("aria-label",open?"Fechar menu":"Abrir menu");});nav.querySelectorAll("a").forEach(link=>link.addEventListener("click",()=>{nav.classList.remove("open");menuToggle.setAttribute("aria-expanded","false");menuToggle.setAttribute("aria-label","Abrir menu");}));}
const sellForm=document.getElementById("sell-form");if(sellForm){sellForm.addEventListener("submit",event=>{event.preventDefault();const data=new FormData(sellForm);const clean=value=>String(value||"-").replace(/[\u0000-\u001f\u007f]/g," ").trim().slice(0,160)||"-";const message=["Olá Braga Veículos! Vim pelo site e quero vender meu carro.",`Nome: ${clean(data.get("nome"))}`,`WhatsApp: ${clean(data.get("telefone"))}`,`Veículo: ${clean(data.get("veiculo"))}`,`Ano: ${clean(data.get("ano"))}`,`KM: ${clean(data.get("km"))}`,`Valor: ${clean(data.get("valor"))}`].join("\n");const url=safeWhatsApp(message);window.open(url,"_blank","noopener,noreferrer");});}
renderInventory();observeReveal(document);
